<widget_code>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  .root { width:100%; height:100%; min-width:0; min-height:0; font-family: var(--font-sans, system-ui, sans-serif); background: var(--bg); color: var(--ink); display: flex; flex-direction: column; }
  .title { font-size: 14px; font-weight: 600; padding: 8px 12px 4px; color: var(--text2); letter-spacing: .02em; }
  .controls { display: flex; gap: 8px; padding: 4px 12px 8px; flex-wrap: wrap; }
  .controls button { font-size: 13px; padding: 5px 14px; border-radius: 6px; border: 1px solid var(--line); background: var(--bg2); color: var(--ink); cursor: pointer; transition: background .12s, transform .12s; }
  .controls button:hover { background: var(--accent); color: var(--bg); border-color: var(--accent); }
  .controls button:active { transform: scale(.97); }
  .controls .step-label { font-size: 12px; color: var(--text2); align-self: center; margin-left: auto; font-variant-numeric: tabular-nums; }
  .stage { flex: 1; display: flex; align-items: center; justify-content: center; padding: 4px 12px 8px; min-height: 0; }
  .stage svg { width: 100%; max-width: 520px; height: auto; display: block; }
  .readout { display: flex; gap: 12px; padding: 4px 12px 8px; font-size: 12px; color: var(--text2); flex-wrap: wrap; }
  .readout span { background: var(--bg2); padding: 3px 10px; border-radius: 4px; border: 1px solid var(--line); }
  .readout .highlight { background: var(--accent); color: var(--bg); border-color: var(--accent); }
</style>
<div class="root">
  <div class="title">LL 旋转演示</div>
  <div class="controls">
    <button id="nextBtn">下一步</button>
    <button id="resetBtn">重置</button>
    <span class="step-label" id="stepLabel">步骤 0 / 3</span>
  </div>
  <div class="stage" id="stage">
    <svg viewBox="0 0 400 240" id="treeSvg">
      <!-- 节点和连线由 JS 绘制 -->
    </svg>
  </div>
  <div class="readout" id="readout">
    <span id="status">初始不平衡</span>
    <span id="bfA">A BF=2</span>
    <span id="bfB">B BF=1</span>
    <span id="bfC">C BF=0</span>
  </div>
</div>
<script>
  (function() {
    const stepLabel = document.getElementById('stepLabel');
    const status = document.getElementById('status');
    const bfA = document.getElementById('bfA');
    const bfB = document.getElementById('bfB');
    const bfC = document.getElementById('bfC');
    const svg = document.getElementById('treeSvg');
    const nextBtn = document.getElementById('nextBtn');
    const resetBtn = document.getElementById('resetBtn');

    let step = 0; // 0..3

    // 数学模型：LL 旋转的树结构
    // 节点坐标 (x, y) 和连线
    function getTree(step) {
      // 返回 { nodes: [{id, label, bf, x, y, highlight}], edges: [{x1,y1,x2,y2}] }
      // step 0: 初始不平衡 A(2) 左子 B(1) 左子 C(0)
      // step 1: 旋转中 — B 的右子树变为 A 的左子树（虚线框）
      // step 2: 旋转完成 — B 为新根，A 为 B 右子，BF 均为 0
      // step 3: 复位到 step 0
      if (step === 0) {
        return {
          nodes: [
            { id: 'A', label: 'A', bf: 2, x: 200, y: 60, highlight: true },
            { id: 'B', label: 'B', bf: 1, x: 120, y: 130, highlight: false },
            { id: 'C', label: 'C', bf: 0, x: 60, y: 200, highlight: false }
          ],
          edges: [
            { x1: 200, y1: 60, x2: 120, y2: 130 },
            { x1: 120, y1: 130, x2: 60, y2: 200 }
          ],
          dashedBox: null
        };
      } else if (step === 1) {
        // 旋转中：B 的右子树（空）变为 A 的左子树，A 成为 B 的右子
        return {
          nodes: [
            { id: 'B', label: 'B', bf: 1, x: 160, y: 60, highlight: false },
            { id: 'A', label: 'A', bf: 2, x: 260, y: 130, highlight: true },
            { id: 'C', label: 'C', bf: 0, x: 80, y: 130, highlight: false }
          ],
          edges: [
            { x1: 160, y1: 60, x2: 80, y2: 130 },
            { x1: 160, y1: 60, x2: 260, y2: 130 }
          ],
          dashedBox: { x: 220, y: 100, w: 100, h: 80 }
        };
      } else if (step === 2) {
        return {
          nodes: [
            { id: 'B', label: 'B', bf: 0, x: 160, y: 60, highlight: false },
            { id: 'C', label: 'C', bf: 0, x: 80, y: 130, highlight: false },
            { id: 'A', label: 'A', bf: 0, x: 260, y: 130, highlight: false }
          ],
          edges: [
            { x1: 160, y1: 60, x2: 80, y2: 130 },
            { x1: 160, y1: 60, x2: 260, y2: 130 }
          ],
          dashedBox: null
        };
      } else {
        // step 3 复位到 step 0
        return getTree(0);
      }
    }

    function render() {
      const tree = getTree(step);
      // 构建 SVG
      let svgContent = '';
      // 虚线框
      if (tree.dashedBox) {
        svgContent += `<rect x="${tree.dashedBox.x}" y="${tree.dashedBox.y}" width="${tree.dashedBox.w}" height="${tree.dashedBox.h}" fill="none" stroke="var(--accent)" stroke-width="1.5" stroke-dasharray="6 4" rx="4" />`;
      }
      // 连线
      for (const e of tree.edges) {
        svgContent += `<line x1="${e.x1}" y1="${e.y1}" x2="${e.x2}" y2="${e.y2}" stroke="var(--line)" stroke-width="1.5" />`;
      }
      // 节点
      for (const n of tree.nodes) {
        const fill = n.highlight ? 'var(--accent)' : 'var(--bg2)';
        const stroke = n.highlight ? 'var(--accent)' : 'var(--line)';
        const textColor = n.highlight ? 'var(--bg)' : 'var(--ink)';
        svgContent += `<g>`;
        svgContent += `<circle cx="${n.x}" cy="${n.y}" r="22" fill="${fill}" stroke="${stroke}" stroke-width="1.5" />`;
        svgContent += `<text x="${n.x}" y="${n.y + 4}" text-anchor="middle" font-size="14" font-weight="600" fill="${textColor}">${n.label}</text>`;
        // 平衡因子标注
        const bfColor = n.bf === 2 ? 'var(--accent)' : 'var(--text2)';
        svgContent += `<text x="${n.x + 30}" y="${n.y - 8}" text-anchor="middle" font-size="11" fill="${bfColor}" font-variant-numeric="tabular-nums">BF=${n.bf}</text>`;
        svgContent += `</g>`;
      }
      svg.innerHTML = svgContent;

      // 更新 readout
      const stepNames = ['初始不平衡', '旋转中', '旋转完成', '初始不平衡'];
      status.textContent = stepNames[step];
      const bfValues = getTree(step).nodes;
      const bfAMap = { A: 'A BF=2', B: 'B BF=1', C: 'C BF=0' };
      const bfBMap = { A: 'A BF=2', B: 'B BF=1', C: 'C BF=0' };
      const bfCMap = { A: 'A BF=0', B: 'B BF=0', C: 'C BF=0' };
      // 根据 step 更新
      if (step === 0) {
        bfA.textContent = 'A BF=2';
        bfB.textContent = 'B BF=1';
        bfC.textContent = 'C BF=0';
        bfA.className = 'highlight';
        bfB.className = '';
        bfC.className = '';
      } else if (step === 1) {
        bfA.textContent = 'A BF=2';
        bfB.textContent = 'B BF=1';
        bfC.textContent = 'C BF=0';
        bfA.className = 'highlight';
        bfB.className = '';
        bfC.className = '';
      } else if (step === 2) {
        bfA.textContent = 'A BF=0';
        bfB.textContent = 'B BF=0';
        bfC.textContent = 'C BF=0';
        bfA.className = '';
        bfB.className = '';
        bfC.className = '';
      } else {
        // step 3 复位
        bfA.textContent = 'A BF=2';
        bfB.textContent = 'B BF=1';
        bfC.textContent = 'C BF=0';
        bfA.className = 'highlight';
        bfB.className = '';
        bfC.className = '';
      }
      stepLabel.textContent = `步骤 ${step} / 3`;
    }

    function update() {
      render();
    }

    function nextStep() {
      step = (step + 1) % 4;
      update();
    }

    function reset() {
      step = 0;
      update();
    }

    nextBtn.addEventListener('click', nextStep);
    resetBtn.addEventListener('click', reset);

    // 初始渲染
    update();

    // verification cases
    console.assert(getTree(0).nodes[0].bf === 2, 'step 0 A BF=2');
    console.assert(getTree(0).nodes[1].bf === 1, 'step 0 B BF=1');
    console.assert(getTree(2).nodes[0].bf === 0, 'step 2 B BF=0');
    console.assert(getTree(2).nodes[2].bf === 0, 'step 2 A BF=0');
  })();
</script>
</widget_code>
